// The vocabulary of the game-detail Settings tab: Old World's own setup
// sections and parameter labels, the display name of every value a setup
// parameter takes, the game options with their help text, and the
// difficulty-mode presets the Difficulty row is matched against. Read by
// `$lib/map-settings`, which builds the rows.

export interface SetupSection {
	/** Section key — also a game option's <Category> value for the five that carry options. */
	readonly key: string;
	/** The heading the setup screen shows, e.g. "Opponent Setup". */
	readonly label: string;
}

// The seven sections Old World's setup screens declare, in setup order.
export const SETUP_SECTIONS: readonly SetupSection[] = [
	{ key: "PLAYER", label: "Player Setup" },
	{ key: "OPPONENTS", label: "Opponent Setup" },
	{ key: "CHARACTERS", label: "Characters and Events" },
	{ key: "VICTORY", label: "Victory Conditions" },
	{ key: "MAP", label: "Map Setup" },
	{ key: "RULES", label: "Game Rules" },
	{ key: "DLC_MOD", label: "DLC and Mods" },
];

export interface SetupParameter {
	/** The root attribute name the save writes, and the setup_parameters key. */
	readonly key: string;
	/** Which SETUP_SECTIONS entry this row belongs to. */
	readonly section: string;
	/** The label the setup screen gives it, e.g. "AI Handicap". */
	readonly label: string;
	/**
	 * formatEnum prefix for this parameter's values, or null for a value the
	 * renderer formats itself (map script, map size, aspect ratio, integer).
	 */
	readonly prefix: string | null;
}

